-- Gold Query
SELECT teamDetails.team_long_name FROM Match AS matchData INNER JOIN Team AS teamDetails ON matchData.home_team_api_id = teamDetails.team_api_id WHERE matchData.season = '2015/2016' AND matchData.home_team_goal - matchData.away_team_goal < 0 GROUP BY matchData.home_team_api_id ORDER BY COUNT(*) ASC, teamDetails.team_long_name NULLS LAST LIMIT 1;

/*
Gold Result:
('James Thomas',)
*/

-- Prediction Query
SELECT team.team_long_name FROM team INNER JOIN (SELECT home_team_api_id, COUNT(*) AS losses FROM match WHERE season = '2015/2016' AND home_team_goal - away_team_goal < 0 GROUP BY home_team_api_id ORDER BY losses ASC, home_team_api_id NULLS LAST LIMIT 1) AS losses ON team.team_api_id = losses.home_team_api_id;

/*
Prediction Result:
('Tiffany Holloway',)
*/